```javascript
const { Command, Argument } = require('discord.js-commando');

module.exports = class BanCommand extends Command {
  constructor(client) {
    super(client, {
      name: 'ban',
      aliases: ['kick'],
      group: 'moderation',
      memberName: 'ban',
      description: 'Bans a member from the server.',
      guildOnly: true,
      args: [
        {
          key: 'member',
          prompt: 'Who do you want to ban?',
          type: 'member',
        },
        {
          key: 'reason',
          prompt: 'Why are you banning them?',
          type: 'string',
          default: 'No reason provided',
        },
      ],
      userPermissions: ['BAN_MEMBERS'],
      botPermissions: ['BAN_MEMBERS'],
    });
  }

  async run(message, { member, reason }) {
    await member.ban({ reason });
    message.reply(`Successfully banned ${member.user.tag} for ${reason}.`);
  }
};
```

5. Konfigurieren des Bots:

Öffnen Sie die Datei `index.js` und fügen Sie den folgenden Code hinzu:

```javascript
const { Collection } = require('discord.js');
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');

const { Client, Commando } = require('discord.js-commando');
const config = require('./config.json');

const client = new Client();
const commandFolder = process.cwd() + '/commands';

const commands = new Collection();
const commandFiles = fs.readdirSync(commandFolder).filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`${commandFolder}/${file}`);
  if (command.name) {
    commands.set(command.name, command);
  } else {
    console.log(`Failed to load command ${file}`);
  }
}

const rest = new REST({ version: '9' }).setToken(config.token);

(async () => {
