Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using namespace std;

int countWordOccurrences(string word, string filename) {
    int count = 0;
    ifstream file(filename);

    if (!file.is_open()) {
        cerr << "Error: Could not open file: " << filename << endl;
        return -1; // return error code
    }

    string line;
    while (getline(file, line)) {
        vector<string> words;
        string token;

        // tokenize the line into individual words
        for (int I = 0; I < line.length(); i++) {
            if (line[i] == ' ') {
                words.push_back(token);
                token = "";
            } else {
                token += line[i];
            }
        }
        words.push_back(token);

        // count occurrences of the specified word
        for (const auto& w : words) {
            if (w == word) {
                count++;
            }
        }
    }

    file.close();
    return count;
}

int main() {
    string word, filename;
    cout << "Enter the word to search for: ";
    cin >> word;
    cout << "Enter the filename: ";
    cin >> filename;

    int occurrences = countWordOccurrences(word, filename);
    if (occurrences == -1) {
        return -1; // exit with error code
    }

    cout << "The word '" << word << "' appears " << occurrences << " times in " << filename << endl;
    return 0;
}
```

Dieses Programm verwendet die folgenden Bibliotheken:

- `iostream`: für Eingabe und Ausgabe
- `fstream`: für die Datei-I/O-Funktionen
- `string`: für den String-Typ
- `vector`: für den Vektor-Typ

Das Programm definiert eine Funktion `countWordOccurrences` mit zwei Argumenten: das Suchwort und der Dateiname. Die Funktion liest die Datei Zeile für Zeile ein und zählt die Anzahl der Vorkommen des Suchworts.

In der `main`-Funktion wird das Suchwort und der Dateiname von der Benutzer-Eingabe gelesen, und die Funktion `countWordOccurrences` wird aufgerufen, um die Anzahl der Vorkommen zu bestimmen. Danach wird das Ergebnis auf der Konsole ausgegeben.

Bitte beachten Sie, dass das Programm derzeit keine Prüfung für das Vorhandensein des Suchworts in der Datei durchführt. Wenn das Suchwort nicht in der Datei gefunden wird, wird die Anzahl der Vorkommen als 0 angezeigt. Wenn das Programm bei der Datei- oder Datei-Eingabeprozessierung einen Fehler aufweist, wird ein negativer Wert zurückgegeben, um das Programm mit einer Fehlermeldung zu beenden.
